<script setup>
import { computed, nextTick, onBeforeUnmount, onMounted, ref } from 'vue'
onMounted(() => { const observer = new MutationObserver(() => { document.querySelectorAll('.courier-history-card').forEach((card) => { if (card.dataset.formatted) return; const strong = card.querySelector('strong'); const date = card.querySelector('span')?.textContent || ''; const value = strong?.textContent?.replace(/^#/, '').split('·'); if (!strong || !value?.length) return; card.dataset.formatted = 'true'; strong.innerHTML = `<small class="courier-history-number">Pedido</small><b>#${value[0].trim()}</b><span class="courier-history-restaurant">${value.slice(1).join('·').trim()}</span>`; const dateNode = card.querySelector('span:not(.courier-history-restaurant)'); if (dateNode) dateNode.innerHTML = `<small class="courier-history-date-label">Completada</small>${date}` }) }); observer.observe(document.body, { childList: true, subtree: true }); onBeforeUnmount(() => observer.disconnect()) })
onMounted(() => { const timer = window.setInterval(() => { if (selectedActiveOrder.value && !assignedOrders.value.some((order) => order.id === selectedActiveOrder.value.id)) selectedActiveOrder.value = null }, 100); onBeforeUnmount(() => window.clearInterval(timer)) })
onMounted(() => { window.addEventListener('click', (event) => { const path = event.composedPath?.() || []; const button = path.find((node) => node?.tagName === 'BUTTON' && node.closest?.('.courier-detail-header') && node.closest?.('.courier-active-delivery')); if (!button) return; event.preventDefault(); event.stopImmediatePropagation(); selectedActiveOrder.value = null; tab.value = 'active' }, true) })
onMounted(() => { window.addEventListener('click', (event) => { const path = event.composedPath?.() || []; const button = path.find((node) => node?.tagName === 'BUTTON' && node.closest?.('.courier-active-delivery .courier-detail-header')); if (!button) return; event.preventDefault(); event.stopImmediatePropagation(); selectedActiveOrder.value = null; tab.value = 'active' }, true) })
onMounted(() => { const timer = window.setInterval(() => { const button = document.querySelector('.courier-active-delivery .courier-detail-header button'); if (!button || button.dataset.backBound) return; button.dataset.backBound = 'true'; button.addEventListener('click', (event) => { event.preventDefault(); event.stopImmediatePropagation(); selectedActiveOrder.value = null; tab.value = 'active' }, true) }, 50); onBeforeUnmount(() => window.clearInterval(timer)) })
onMounted(() => { const timer = window.setInterval(() => { if (tab.value !== 'active') { document.querySelector('.courier-active-orders')?.remove(); document.querySelector('.courier-active-list')?.remove(); selectedActiveOrder.value = null } }, 50); onBeforeUnmount(() => window.clearInterval(timer)) })
onMounted(() => { document.addEventListener('click', (event) => { const back = event.target.closest('.courier-active-delivery .courier-detail-header button'); if (!back) return; event.preventDefault(); event.stopImmediatePropagation(); selectedActiveOrder.value = null; tab.value = 'active' }, true) })
onMounted(() => { const timer = window.setInterval(() => { const detail = document.querySelector('.courier-active-delivery'); if (!detail) return; detail.style.visibility = tab.value === 'active' && !selectedActiveOrder.value ? 'hidden' : 'visible' }, 50); onBeforeUnmount(() => window.clearInterval(timer)) })
onMounted(() => { const timer = window.setInterval(() => { const detail = document.querySelector('.courier-active-delivery'); if (!detail || tab.value !== 'active' || assignedOrders.value.length < 1 || selectedActiveOrder.value) return; detail.style.display = 'none'; if (document.querySelector('.courier-active-orders')) return; const list = document.createElement('section'); list.className = 'courier-active-orders'; list.innerHTML = '<h2>Entregas activas</h2>'; assignedOrders.value.forEach((order) => { const card = document.createElement('button'); card.className = 'courier-active-order-card'; card.innerHTML = `<strong>#${order.numero} · ${order.restaurantes?.nombre || 'Restaurante'}</strong><span>${order.direcciones?.detalle || order.direccion_snapshot || 'Dirección de entrega'}</span><small>Entrar a esta entrega →</small>`; card.addEventListener('click', () => { selectedActiveOrder.value = order; list.remove(); detail.style.display = '' }); list.append(card) }); detail.parentElement?.prepend(list) }, 200); onBeforeUnmount(() => window.clearInterval(timer)) })
onMounted(() => { const renderActiveList = () => { const card = document.querySelector('.courier-active-card'); if (!card || tab.value !== 'active' || assignedOrders.value.length < 2) return; if (selectedActiveOrder.value) { document.querySelector('.courier-active-list')?.remove(); card.style.display = ''; return } card.style.display = 'none'; let list = document.querySelector('.courier-active-list'); if (!list) { list = document.createElement('section'); list.className = 'courier-active-list'; list.innerHTML = '<h2>Entregas activas</h2>'; assignedOrders.value.forEach((item) => { const button = document.createElement('button'); button.innerHTML = `<strong>#${item.numero} · ${item.restaurantes?.nombre || 'Restaurante'}</strong><small>${item.direcciones?.detalle || item.direccion_snapshot || 'Dirección de entrega'}</small><span>Ver entrega →</span>`; button.addEventListener('click', () => { selectedActiveOrder.value = item }); list.append(button) }); card.parentElement?.prepend(list) } }; const timer = window.setInterval(renderActiveList, 200); document.addEventListener('click', (event) => { if (event.target.closest('.courier-bottom-nav button:nth-child(2)')) selectedActiveOrder.value = null }, true); onBeforeUnmount(() => window.clearInterval(timer)) })
onMounted(() => { const updateBadge = () => { const button = document.querySelector('.courier-bottom-nav button:nth-child(2)'); if (!button) return; let badge = button.querySelector('.courier-active-badge'); if (assignedOrders.value.length && !badge) { badge = document.createElement('b'); badge.className = 'courier-active-badge'; button.append(badge) } if (badge) { badge.textContent = String(assignedOrders.value.length); badge.style.display = assignedOrders.value.length ? 'grid' : 'none' } }; const timer = window.setInterval(updateBadge, 200); onBeforeUnmount(() => window.clearInterval(timer)) })
onMounted(() => { const observer = new MutationObserver(() => { document.querySelectorAll('.courier-request-card').forEach((card) => { if (card.querySelector('.courier-distance')) return; const number = card.querySelector('.courier-request-card__top strong')?.textContent?.replace('#', '').trim(); const item = requests.value.find((request) => String(request.numero) === number); const restaurant = item?.restaurantes; const destination = item?.direcciones; const lat1 = Number(restaurant?.pos_y); const lon1 = Number(restaurant?.pos_x); const lat2 = Number(destination?.latitud); const lon2 = Number(destination?.longitud); if (![lat1, lon1, lat2, lon2].every(Number.isFinite)) return; const radians = (value) => value * Math.PI / 180; const a = Math.sin(radians(lat2 - lat1) / 2) ** 2 + Math.cos(radians(lat1)) * Math.cos(radians(lat2)) * Math.sin(radians(lon2 - lon1) / 2) ** 2; const distance = 6371 * 2 * Math.atan2(Math.sqrt(a), Math.sqrt(1 - a)); const label = document.createElement('span'); label.className = 'courier-distance'; label.textContent = `${distance.toFixed(1)} km`; card.querySelector('.courier-request-card__top')?.append(label) }) }); observer.observe(document.body, { childList: true, subtree: true }); onBeforeUnmount(() => observer.disconnect()) })
onMounted(() => { document.addEventListener('click', (event) => { const button = event.target.closest('.courier-dismiss-button'); if (!button) return; const card = button.closest('.courier-request-card'); const number = card?.querySelector('.courier-request-card__top strong')?.textContent?.replace('#', '').trim(); const item = requests.value.find((request) => String(request.numero) === number); if (!item || !dismissedRequestIds.value.has(item.id)) return; button.textContent = 'Deshacer'; event.preventDefault(); event.stopImmediatePropagation(); restoreRequest(item); button.textContent = 'Descartar' }, true) })
const showDismissed = ref(false)
onMounted(() => { const timer = window.setInterval(() => { const header = document.querySelector('.courier-header'); const icon = header?.querySelector('svg'); if (!header || !icon) return; let badge = header.querySelector('.courier-notification-badge'); if (requests.value.length) { if (!badge) { badge = document.createElement('b'); badge.className = 'courier-notification-badge'; header.append(badge) }; badge.textContent = String(requests.value.length) } else badge?.remove() }, 250); onBeforeUnmount(() => window.clearInterval(timer)) })
onMounted(() => { const saved = JSON.parse(localStorage.getItem('pedidosya-dismissed-courier-requests') || '[]'); dismissedRequestIds.value = new Set(saved); const observer = new MutationObserver(() => { const title = document.querySelector('.courier-section-title'); if (title && !title.querySelector('.courier-dismissed-toggle')) { const toggle = document.createElement('button'); toggle.className = 'courier-dismissed-toggle'; toggle.textContent = 'Ver descartadas'; toggle.addEventListener('click', () => { showDismissed.value = !showDismissed.value; toggle.textContent = showDismissed.value ? 'Ocultar descartadas' : 'Ver descartadas'; observer.takeRecords(); document.querySelectorAll('.courier-request-card').forEach((card) => { const number = card.querySelector('.courier-request-card__top strong')?.textContent?.replace('#', '').trim(); const item = requests.value.find((request) => String(request.numero) === number); if (item && dismissedRequestIds.value.has(item.id)) card.style.display = showDismissed.value ? '' : 'none' }) }) ; title.append(toggle) } document.querySelectorAll('.courier-request-card').forEach((card) => { const number = card.querySelector('.courier-request-card__top strong')?.textContent?.replace('#', '').trim(); const item = requests.value.find((request) => String(request.numero) === number); if (item && dismissedRequestIds.value.has(item.id)) card.style.display = showDismissed.value ? '' : 'none' }) }); observer.observe(document.body, { childList: true, subtree: true }); onBeforeUnmount(() => observer.disconnect()) })
onMounted(() => { const observer = new MutationObserver(() => { document.querySelectorAll('.courier-request-card').forEach((card) => { if (card.dataset.detailsBound) return; card.dataset.detailsBound = 'true'; card.addEventListener('click', (event) => { if (event.target.closest('button')) return; const number = card.querySelector('.courier-request-card__top strong')?.textContent?.replace('#', '').trim(); const item = requests.value.find((request) => String(request.numero) === number); if (item) selectedRequest.value = item }) }) }); observer.observe(document.body, { childList: true, subtree: true }); onBeforeUnmount(() => observer.disconnect()) })
onMounted(() => { const observer = new MutationObserver(() => { document.querySelectorAll('.courier-request-card').forEach((card) => { if (card.querySelector('.courier-dismiss-button')) return; const number = card.querySelector('.courier-request-card__top strong')?.textContent?.replace('#', '').trim(); const item = requests.value.find((request) => String(request.numero) === number); if (!item) return; const button = document.createElement('button'); button.className = 'courier-secondary courier-dismiss-button'; button.textContent = 'Descartar'; button.addEventListener('click', () => dismissRequest(item)); card.querySelector('.courier-card-actions')?.prepend(button); const restaurant = item.restaurantes; const destination = item.direcciones; const lat1 = Number(restaurant?.latitud ?? restaurant?.lat); const lon1 = Number(restaurant?.longitud ?? restaurant?.lon); const lat2 = Number(destination?.latitud ?? destination?.lat); const lon2 = Number(destination?.longitud ?? destination?.lon); if ([lat1, lon1, lat2, lon2].every(Number.isFinite) && !card.querySelector('.courier-distance')) { const radians = (value) => value * Math.PI / 180; const a = Math.sin(radians(lat2 - lat1) / 2) ** 2 + Math.cos(radians(lat1)) * Math.cos(radians(lat2)) * Math.sin(radians(lon2 - lon1) / 2) ** 2; const distance = 6371 * 2 * Math.atan2(Math.sqrt(a), Math.sqrt(1 - a)); const label = document.createElement('span'); label.className = 'courier-distance'; label.textContent = `${distance < 1 ? `${Math.round(distance * 1000)} m` : `${distance.toFixed(1)} km`} de recorrido`; card.querySelector('.courier-request-card__top')?.append(label) } }) }); observer.observe(document.body, { childList: true, subtree: true }); onBeforeUnmount(() => observer.disconnect()) })
import { Bell, Check, History, Home, LogOut, MapPin, UserRound, Truck } from 'lucide-vue-next'
import { useRouter } from 'vue-router'; import { useSessionStore } from '../stores/session'; import CourierRequestMap from '../components/CourierRequestMap.vue'; import CourierActiveDelivery from '../components/CourierActiveDelivery.vue'; import DeliveryLocationPicker from '../components/DeliveryLocationPicker.vue'; import { acceptCourierRequest, getCourierProfile, listCourierAssignedOrders, listCourierHistory, listCourierRequests, subscribeCourierRequests, toggleCourierAvailability, updateCourierLocation, updateCourierOrderState } from '../services/courierService'; import '../assets/courier.css'; import '../assets/courier-detail.css'; import '../assets/courier-card-actions.css'; import '../assets/courier-products.css'; import '../assets/courier-totals.css'; import '../assets/courier-active-delivery.css'
const router = useRouter(); const session = useSessionStore(); const courier = ref(null); const requests = ref([]); const dismissedRequestIds = ref(new Set()); const assignedOrders = ref([]); const history = ref([]); const selectedRequest = ref(null); const tab = ref('home'); const loading = ref(true); const error = ref(''); const accepting = ref(null); const updating = ref(null); const locationUpdating = ref(false); const locationPickerOpen = ref(false); const pendingAcceptance = ref(null); const acceptanceLocation = ref(null); let unsubscribe
const selectedActiveOrder = ref(null)
const requestNotice = ref('')
const knownRequestIds = ref(null)
let requestNoticeTimer
let realtimeRefreshTimer
async function refreshRequests() { if (!courier.value) return; try { const next = await listCourierRequests(); const currentIds = new Set(next.map((item) => item.id)); if (knownRequestIds.value && next.some((item) => !knownRequestIds.value.has(item.id))) { requestNotice.value = 'Tienes una nueva solicitud de entrega'; window.clearTimeout(requestNoticeTimer); requestNoticeTimer = window.setTimeout(() => { requestNotice.value = '' }, 5000) }; knownRequestIds.value = currentIds; requests.value = next } catch (e) { error.value = e.message || 'No se pudieron actualizar las solicitudes.' } }
let requestRefreshTimer
const activeOrder = computed(() => selectedActiveOrder.value || assignedOrders.value[0] || null)
const visibleRequests = computed(() => requests.value.filter((item) => !dismissedRequestIds.value.has(item.id)))
function goToClientView() { router.push('/') }
function dismissRequest(item) { dismissedRequestIds.value = new Set([...dismissedRequestIds.value, item.id]); localStorage.setItem('pedidosya-dismissed-courier-requests', JSON.stringify([...dismissedRequestIds.value])); const card = [...document.querySelectorAll('.courier-request-card')].find((element) => element.textContent.includes(`#${item.numero}`)); if (card) card.style.display = showDismissed.value ? '' : 'none'; if (selectedRequest.value?.id === item.id) selectedRequest.value = null }
function restoreRequest(item) { const next = new Set(dismissedRequestIds.value); next.delete(item.id); dismissedRequestIds.value = next; localStorage.setItem('pedidosya-dismissed-courier-requests', JSON.stringify([...next])); const card = [...document.querySelectorAll('.courier-request-card')].find((element) => element.textContent.includes(`#${item.numero}`)); if (card) card.style.display = ''; }
async function addDismissActions() { await nextTick(); document.querySelectorAll('.courier-request-card').forEach((card) => { if (card.querySelector('.courier-dismiss-button')) return; const number = card.querySelector('.courier-request-card__top strong')?.textContent?.replace('#', '').trim(); const button = document.createElement('button'); button.className = 'courier-secondary courier-dismiss-button'; button.textContent = 'Descartar'; button.addEventListener('click', () => { const item = requests.value.find((request) => String(request.numero) === number); if (item) dismissRequest(item) }); card.querySelector('.courier-card-actions')?.prepend(button) }) }
async function load() { try { courier.value = await getCourierProfile(session.user.id); if (courier.value) { assignedOrders.value = await listCourierAssignedOrders(courier.value.id); requests.value = courier.value.disponible ? await listCourierRequests() : []; history.value = await listCourierHistory(courier.value.id); const currentIds = new Set(requests.value.map((item) => item.id)); if (knownRequestIds.value && requests.value.some((item) => !knownRequestIds.value.has(item.id))) { requestNotice.value = 'Tienes una nueva solicitud de entrega'; window.clearTimeout(requestNoticeTimer); requestNoticeTimer = window.setTimeout(() => { requestNotice.value = '' }, 5000) }; knownRequestIds.value = currentIds; if (selectedActiveOrder.value) selectedActiveOrder.value = assignedOrders.value.find((item) => item.id === selectedActiveOrder.value.id) || null } if (selectedRequest.value && !requests.value.some((item) => item.id === selectedRequest.value.id)) selectedRequest.value = { ...selectedRequest.value, unavailable: true } } catch (e) { error.value = e.message || 'No se pudo cargar el panel.' } finally { loading.value = false } }
async function availability() { try { await toggleCourierAvailability(!courier.value.disponible); await load() } catch (e) { error.value = e.message } }; async function performAccept(item, location) { accepting.value = item.id; try { await acceptCourierRequest(item.id, location); selectedRequest.value = null; tab.value = 'active'; acceptanceLocation.value = null; await load() } catch (e) { error.value = e.message?.includes('SOLICITUD_YA_ACEPTADA') ? 'Esta entrega ya fue aceptada por otro repartidor.' : e.message } finally { accepting.value = null } }; async function accept(item) { if (!acceptanceLocation.value) { pendingAcceptance.value = item; locationPickerOpen.value = true; return }; await performAccept(item, acceptanceLocation.value) }; async function confirmAcceptanceLocation(point) { acceptanceLocation.value = point; locationPickerOpen.value = false; if (pendingAcceptance.value) { const item = pendingAcceptance.value; pendingAcceptance.value = null; await performAccept(item, point) } }; async function updateLocation(point) { if (!activeOrder.value) return; locationUpdating.value = true; error.value = ''; try { const saved = await updateCourierLocation(activeOrder.value.id, point); const timestamp = saved?.ubicacion_actualizada_en || new Date().toISOString(); assignedOrders.value = assignedOrders.value.map((item) => item.id === activeOrder.value.id ? { ...item, repartidor_ubicacion: { pos_x: Number(point.longitud), pos_y: Number(point.latitud), actualizada_en: timestamp } } : item); await load() } catch (e) { const message = e?.message || ''; error.value = message.includes('ENTREGA_NO_ACTIVA') ? 'Esta entrega ya no está activa.' : message.includes('REPARTIDOR_NO_ASIGNADO') ? 'Ya no eres el repartidor asignado a esta entrega.' : message || 'No se pudo actualizar tu ubicación.' } finally { locationUpdating.value = false } }; async function advance(state) { updating.value = true; try { await updateCourierOrderState(activeOrder.value.id, state); await load() } catch (e) { error.value = e.message } finally { updating.value = false } }; async function logout() { await session.signOut(); router.replace('/') }; onMounted(async () => { await load(); await refreshRequests(); unsubscribe = subscribeCourierRequests(() => { clearTimeout(realtimeRefreshTimer); realtimeRefreshTimer = window.setTimeout(refreshRequests, 400) }); requestRefreshTimer = window.setInterval(refreshRequests, 3000); document.addEventListener('visibilitychange', refreshRequests) }); onBeforeUnmount(() => { unsubscribe?.(); clearTimeout(realtimeRefreshTimer); if (requestRefreshTimer) window.clearInterval(requestRefreshTimer); if (requestNoticeTimer) window.clearTimeout(requestNoticeTimer); document.removeEventListener('visibilitychange', refreshRequests) })
</script>
<template><main class="courier-page"><header class="courier-header"><div><span>REPARTIDOR</span><h1>Hola, {{ session.profile?.nombre?.split(' ')[0] || 'repartidor' }}</h1><p>{{ courier?.zonas?.nombre || 'Sin zona asignada' }}</p></div><Bell :size="20" /></header><section class="courier-content"><p v-if="error" class="courier-error">{{ error }}</p><div v-if="loading" class="courier-empty">Cargando…</div><template v-else><CourierActiveDelivery v-if="tab === 'active' && activeOrder" :order="activeOrder" :updating="updating" :location-updating="locationUpdating" @advance="advance" @update-location="updateLocation" @back="tab = 'home'" /><section v-else-if="selectedRequest" class="courier-detail-card"><div class="courier-detail-header"><button @click="selectedRequest = null">←</button><h2>Detalle de solicitud</h2></div><div v-if="selectedRequest.unavailable" class="courier-empty courier-empty--compact"><h2>Esta solicitud ya no está disponible</h2><button class="courier-text-button" @click="selectedRequest = null">Volver</button></div><template v-else><span class="courier-request-label">SOLICITUD · #{{ selectedRequest.numero }}</span><h1>{{ selectedRequest.restaurantes?.nombre }}</h1><p class="courier-order-state">Lista para recoger</p><CourierRequestMap :restaurant="selectedRequest.restaurantes" /><div class="courier-detail-meta"><div><MapPin :size="18" /><span><b>Recogida</b><br />{{ selectedRequest.restaurantes?.nombre }}<br />{{ selectedRequest.restaurantes?.zonas?.nombre }}</span></div><div><MapPin :size="18" /><span><b>Entrega</b><br />{{ selectedRequest.direcciones?.detalle || selectedRequest.direccion_snapshot }}<br />{{ selectedRequest.direcciones?.zonas?.nombre }}</span></div></div><div class="courier-detail-section"><h3>Productos</h3><div v-for="line in selectedRequest.pedido_detalles || []" :key="line.id" class="courier-product-line"><img v-if="line.productos?.imagen_url" :src="line.productos.imagen_url" :alt="line.nombre_producto_snapshot" /><div><strong>{{ line.cantidad }} × {{ line.nombre_producto_snapshot }}</strong><small>${{ Number(line.subtotal_linea || 0).toFixed(2) }}</small></div></div></div><div class="courier-detail-section courier-totals"><div><span>Subtotal</span><strong>${{ Number(selectedRequest.subtotal || 0).toFixed(2) }}</strong></div><div><span>Envío</span><strong>${{ Number(selectedRequest.costo_envio || 0).toFixed(2) }}</strong></div><div class="total"><span>Total</span><strong>${{ Number(selectedRequest.total || 0).toFixed(2) }}</strong></div></div><div class="courier-detail-actions"><button class="secondary" @click="selectedRequest = null">Volver</button><button class="courier-accept" @click="accept(selectedRequest)"><Check :size="18" /> Aceptar entrega</button></div></template></section><template v-else-if="tab === 'home'"><div class="courier-availability"><div><strong>{{ courier?.disponible ? 'Disponible' : 'No disponible' }}</strong><small>{{ activeOrder ? 'Entrega activa' : 'Puedes recibir solicitudes' }}</small></div><button class="courier-switch" :class="{ active: courier?.disponible }" :disabled="false" @click="availability"><span /></button></div><div class="courier-summary-grid"><div><b>{{ history.length }}</b><small>Completadas</small></div><div><b>{{ assignedOrders.length }}</b><small>Activas</small></div><div><b>{{ requests.length }}</b><small>Solicitudes</small></div></div><h2 class="courier-section-title">Solicitudes disponibles</h2><div v-if="!requests.length" class="courier-empty courier-empty--compact"><MapPin :size="38" /><h2>Estás disponible</h2><p>Te avisaremos cuando haya nuevas entregas.</p></div><TransitionGroup v-else name="courier-request" tag="div" class="courier-requests"><article v-for="request in requests" :key="request.id" class="courier-request-card"><span class="courier-request-label">NUEVA SOLICITUD</span><div class="courier-request-card__top"><h2>{{ request.restaurantes?.nombre }}</h2><strong>#{{ request.numero }}</strong></div><div class="courier-route"><span><MapPin :size="16" /> Recoger en: {{ request.restaurantes?.nombre }}</span><span><MapPin :size="16" /> Entregar en: {{ request.direcciones?.detalle || request.direcciones?.zonas?.nombre || 'Dirección disponible' }}</span></div><small>{{ request.pedido_detalles?.reduce((total, line) => total + line.cantidad, 0) || 0 }} productos</small><div class="courier-card-actions"><button class="courier-secondary" @click="selectedRequest = request">Ver detalles</button><button class="courier-accept" :disabled="accepting === request.id" @click="accept(request)"><Check :size="18" /> Aceptar</button></div></article></TransitionGroup></template><section v-else-if="tab === 'history'"><div v-if="!history.length" class="courier-empty"><History :size="38" /><h2>Aún no tienes entregas</h2></div><div v-else class="courier-history-list"><article v-for="item in history" :key="item.id" class="courier-history-card"><strong>#{{ item.numero }} · {{ item.restaurantes?.nombre }}</strong><span>{{ new Date(item.terminada_en).toLocaleDateString('es-SV') }}</span></article></div></section><section v-else class="courier-profile-card"><UserRound :size="34" /><h2>{{ session.profile?.nombre }}</h2><p>{{ session.user?.email }}</p><button class="courier-text-button courier-client-view-button" @click="goToClientView"><Home :size="17" /> Volver a cliente</button><button class="courier-text-button" @click="logout"><LogOut :size="17" /> Cerrar sesión</button></section></template></section><nav class="courier-bottom-nav"><button :class="{ active: tab === 'home' }" @click="tab = 'home'"><Home :size="20" /><span>Inicio</span></button><button :class="{ active: tab === 'active' }" @click="tab = 'active'"><Truck :size="20" /><span>Entrega activa</span></button><button :class="{ active: tab === 'history' }" @click="tab = 'history'"><History :size="20" /><span>Historial</span></button><button :class="{ active: tab === 'profile' }" @click="tab = 'profile'"><UserRound :size="20" /><span>Mi perfil</span></button></nav><DeliveryLocationPicker v-if="locationPickerOpen" :latitud="acceptanceLocation?.latitud" :longitud="acceptanceLocation?.longitud" :restaurant="pendingAcceptance?.restaurantes" :destination="pendingAcceptance?.direcciones" mode="courier" @cancel="locationPickerOpen = false; pendingAcceptance = null" @confirm="confirmAcceptanceLocation" /></main></template>
